public static boolean validateWorkerAssignmentOverlap(
    HcmPositionWorkerAssignment          _hcmPositionWorkerAssignment,
    HcmPositionWorkerAssignmentStartDate _newValidFrom,
    HcmPositionWorkerAssignmentEndDate   _newValidTo)
{
    boolean ret;

    ret = next validateWorkerAssignmentOverlap(
        _hcmPositionWorkerAssignment,
        _newValidFrom,
        _newValidTo);

    if (!ret)
    {
        if (HcmPositionTransition::nvAllowWorkerAssignmentOverlap(
                _hcmPositionWorkerAssignment,
                _newValidFrom,
                _newValidTo))
        {
            ret = true;
        }
    }

    return ret;
}

private static boolean nvAllowWorkerAssignmentOverlap(
    HcmPositionWorkerAssignment          _hcmPositionWorkerAssignment,
    HcmPositionWorkerAssignmentStartDate _newValidFrom,
    HcmPositionWorkerAssignmentEndDate   _newValidTo)
{
    HcmPositionRecId positionRecId = _hcmPositionWorkerAssignment.Position;

    if (!positionRecId)
    {
        return false;
    }

    if (!HcmPosition::isActiveAtTime(positionRecId, _newValidFrom))
    {
        return false;
    }

    if(_newValidTo == DateTimeUtil::maxValue())
    {
        return false;
    }
    return true;
}
